1	export interface Item {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	}
7	
8	export interface Damage {
9	  itemType: string;
10	  amount: number;
11	}
12	
13	export interface Incident {
14	  cause: string;
15	  damages: Damage[];
16	}
17	
18	export type Step =
19	  | { op: "quote"; items: Item[] }
20	  | { op: "claim"; policy: number; incident: Incident };
21	
22	export interface Customer {
23	  yearsWithMHPCO: number;
24	}
25	
26	export interface Scenario {
27	  customer: Customer;
28	  steps: Step[];
29	}
30	
31	export type QuoteResult = { premium: number };
32	export type ClaimResult = { payout: number; remainingCap: number };
33	export type Result = QuoteResult | ClaimResult;
34	
35	export interface ScenarioOutcome {
36	  results: Result[];
37	}
38	
39	/** Rounds up to whole G (the MHPCO's favour), ignoring binary floating-point noise. */
40	const roundUpToWholeG = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
41	
42	const BASE_PREMIUM: Record<string, number> = {
43	  sword: 100,
44	  amulet: 60,
45	  staff: 80,
46	  potion: 40,
47	  rune: 25,
48	  moonstone: 25,
49	};
50	
51	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
52	const POLICY_FEE = 5;
53	
54	const COMPONENT_TYPES = ["rune", "moonstone"];
55	const BUILDING_BLOCK_SIZE = 3;
56	const BUILDING_BLOCK_BASE_PREMIUM = 60;
57	
58	const isComponent = (item: Item): boolean => COMPONENT_TYPES.includes(item.type);
59	
60	const sum = (amounts: number[]): number => amounts.reduce((a, b) => a + b, 0);
61	
62	const countOfType = (items: Item[], type: string): number =>
63	  items.filter((item) => item.type === type).length;
64	
65	/**
66	 * Components of one kind are bundled into building blocks of 3, each charged at
67	 * the special block rate; leftovers are charged individually.
68	 */
69	const componentGroupBasePremium = (type: string, count: number): number => {
70	  const blocks = Math.floor(count / BUILDING_BLOCK_SIZE);
71	  const singles = count % BUILDING_BLOCK_SIZE;
72	  return blocks * BUILDING_BLOCK_BASE_PREMIUM + singles * BASE_PREMIUM[type];
73	};
74	
75	const CURSED_SURCHARGE_RATE = 0.5;
76	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
77	const HIGH_ENCHANTMENT_LEVEL = 5;
78	
79	/**
80	 * A premium modifier as a multiplicative factor: a positive rate loads the premium,
81	 * a negative rate discounts it, and a modifier that does not apply leaves it untouched.
82	 */
83	const rateFactor = (applies: boolean, rate: number): number => (applies ? 1 + rate : 1);
84	
85	const isCursed = (item: Item): boolean => item.cursed === true;
86	const isHighlyEnchanted = (item: Item): boolean =>
87	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
88	
89	/** Risk surcharges attach to the individual item that carries the risk, and compound. */
90	const riskMultiplierOf = (item: Item): number =>
91	  rateFactor(isCursed(item), CURSED_SURCHARGE_RATE) *
92	  rateFactor(isHighlyEnchanted(item), HIGH_ENCHANTMENT_SURCHARGE_RATE);
93	
94	/** Main items are priced one by one off the base price list, each carrying its own risk load. */
95	const mainItemsPremium = (items: Item[]): number =>
96	  sum(
97	    items
98	      .filter((item) => !isComponent(item))
99	      .map((item) => BASE_PREMIUM[item.type] * riskMultiplierOf(item)),
100	  );
101	
102	/**
103	 * Components are priced per kind, so alike ones can bundle into building blocks.
104	 * Pricing by count means individual risk flags are not visible here — no test covers
105	 * a cursed component yet, so this stays as-is rather than being fixed speculatively.
106	 */
107	const componentsPremium = (items: Item[]): number =>
108	  sum(COMPONENT_TYPES.map((type) => componentGroupBasePremium(type, countOfType(items, type))));
109	
110	/** Base price list plus per-item risk loading — everything before customer-level modifiers. */
111	const riskLoadedPremiumOf = (items: Item[]): number =>
112	  mainItemsPremium(items) + componentsPremium(items);
113	
114	const LOYALTY_DISCOUNT_RATE = -0.2;
115	/** Loyalty begins at the start of the second year: 1 year does not qualify, 2 do. */
116	const LOYALTY_THRESHOLD_YEARS = 2;
117	
118	const isLoyal = (customer: Customer): boolean =>
119	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
120	
121	const CONTRACT_DISCOUNT_RATE = -0.15;
122	
123	/**
124	 * Customer-level modifiers apply to the whole quote and compound. A customer's very
125	 * first insurance carries the assessment surcharge; every contract after it is
126	 * discounted instead. `previousQuotes` counts quotes already given to this customer.
127	 */
128	const customerMultiplierOf = (customer: Customer, previousQuotes: number): number => {
129	  const isFirstInsurance = previousQuotes === 0;
130	  return (
131	    rateFactor(isLoyal(customer), LOYALTY_DISCOUNT_RATE) *
132	    rateFactor(isFirstInsurance, FIRST_INSURANCE_SURCHARGE_RATE) *
133	    rateFactor(!isFirstInsurance, CONTRACT_DISCOUNT_RATE)
134	  );
135	};
136	
137	const quote = (items: Item[], customer: Customer, previousQuotes: number): QuoteResult => {
138	  const premiumBeforeFee =
139	    riskLoadedPremiumOf(items) * customerMultiplierOf(customer, previousQuotes);
140	  return { premium: roundUpToWholeG(premiumBeforeFee) + POLICY_FEE };
141	};
142	
143	/**
144	 * Steps are not independent: each one is answered in the light of the steps before it,
145	 * so the scenario is walked as a fold that threads what has happened so far.
146	 */
147	interface ScenarioState {
148	  quotesSoFar: number;
149	}
150	
151	const INITIAL_STATE: ScenarioState = { quotesSoFar: 0 };
152	
153	const applyStep = (
154	  state: ScenarioState,
155	  step: Step,
156	  customer: Customer,
157	): { state: ScenarioState; result: Result } => {
158	  if (step.op === "quote") {
159	    return {
160	      state: { quotesSoFar: state.quotesSoFar + 1 },
161	      result: quote(step.items, customer, state.quotesSoFar),
162	    };
163	  }
164	  throw new Error("claim steps are not implemented yet");
165	};
166	
167	export const runScenario = (scenario: Scenario): ScenarioOutcome => {
168	  const results: Result[] = [];
169	  let state = INITIAL_STATE;
170	  for (const step of scenario.steps) {
171	    const stepOutcome = applyStep(state, step, scenario.customer);
172	    state = stepOutcome.state;
173	    results.push(stepOutcome.result);
174	  }
175	  return { results };
176	};
